#!/usr/bin/env bash
# =============================================================================
# AlphaCP — D1 EMAIL DEPTH FIX v1.0  (live panel 0.75.x line · 09 Oct 2026)
#
# Depth Wave D1: Email Accounts + Forwarders ab cPanel jaise option-by-option.
# 6 files (koi DB migration/composer NAHI — sirf controller/routes/views/assets):
#   1. app/Http/Controllers/MailController.php  -> NEW update() (quota edit +
#      password change via declarative mail.set) + per-box disk usage (readonly
#      mail.usage, page kabhi nahi tootta) + Connect Devices data
#   2. routes/web.php                           -> + PUT /email/{mailbox} (email.update)
#   3. resources/views/email/index.blade.php    -> cPanel-style: stats strip, search,
#      usage bars, Manage (quota/password) + Connect Devices (IMAP 993/POP3 995/
#      SMTP 465 + copy chips), create form (password generator + strength meter,
#      quota MB-ya-Unlimited), default account card
#   4. resources/views/forwarders/index.blade.php -> cPanel-style list + search + create
#   5. public/assets/panel.js  (v1.1)           -> pw generator/meter/show, row filter,
#      quota radio, copy chips (sab CSP-safe external JS)
#   6. public/assets/panel.css (v3.2)           -> pw-meter, expanders, subrow styles
# Safety: har file backup (.bak-d1email-<stamp>) -> install -> view:clear +
#   route:clear + php-fpm graceful reload -> health 8090/2083/2087 ->
#   fail par AUTO-ROLLBACK.
# =============================================================================
set -Eeuo pipefail

D1_VERSION="1.0"
PANEL_ROOT="${PANEL_ROOT:-/usr/local/alphacp/panel}"
STAMP="$(date -u +%Y%m%d%H%M%S)"
LOG_FILE="/var/log/alphacp-d1-email-fix.log"

C_B=$'\033[1m'; C_G=$'\033[32m'; C_R=$'\033[31m'; C_Y=$'\033[33m'; C_0=$'\033[0m'
say() { printf '%s\n' "$*"; }
log() { printf '%s [%s]\n' "$(date -u '+%F %T')Z" "$*" >>"${LOG_FILE}" 2>/dev/null || true; }
ok()  { log "OK   $*"; say "${C_G}[OK]${C_0} $*"; }
warn(){ log "WARN $*"; say "${C_Y}[!]${C_0} $*"; }
die() { log "FAIL $*"; say "${C_R}[x]${C_0} $*"; say "Log: ${LOG_FILE}"; exit 1; }

say ""
say "${C_B}== AlphaCP D1 EMAIL DEPTH FIX v${D1_VERSION} ==${C_0}"
[[ "${EUID}" -eq 0 ]] || die "root chahiye: sudo bash $0"
[[ -d "${PANEL_ROOT}/public/assets" ]] || die "panel nahi mila: ${PANEL_ROOT}"
[[ -f "${PANEL_ROOT}/public/assets/panel.js" ]] || die "pehle theme-fix v1.2 install karo (panel.js missing) — COMMANDS.md dekho"

F0_PATH="app/Http/Controllers/MailController.php"
